import java.util.*;
import java.util.stream.*;
import java.nio.file.*;
import java.io.IOException;

public class StreamCreationMethods {
    public static void main(String[] args) throws IOException {
        // 1. From Collection
        var orders = List.of("Order1", "Order2", "Order3");
        Stream<String> collectionStream = orders.stream();

        // 2. From Array
        String[] orderArray = {"Order1", "Order2"};
        Stream<String> arrayStream = Arrays.stream(orderArray);

        // 3. From Static Factory
        Stream<String> ofStream = Stream.of("Order1", "Order2");

        // 4. From Generator (infinite)
        Stream<Double> randomStream = Stream.generate(Math::random)
            .limit(5);  // Must limit infinite streams

        // 5. From Iterator (infinite sequence)
        Stream<Integer> iterateStream = Stream.iterate(1, n -> n * 2)
            .limit(10);  // Generates 1, 2, 4, 8, 16...

        // 6. From File
        Stream<String> fileStream = Files.lines(Path.of("orders.txt"));
    }
}

import java.util.List;
import java.util.Optional;

public class LazyEvaluationDemo {
    public static void main(String[] args) {
        var orders = List.of(
            new Order(1L, "Laptop", 500),
            new Order(2L, "Mouse", 25),
            new Order(3L, "Monitor", 300),
            new Order(4L, "Keyboard", 80)
        );

        // Lazy: filter and map don't execute here
        Optional<String> firstExpensive = orders.stream()
            .filter(o -> {
                System.out.println("Filtering: " + o.item());
                return o.price() > 100;
            })
            .map(o -> {
                System.out.println("Mapping: " + o.item());
                return o.item().toUpperCase();
            })
            .findFirst();  // Terminal op triggers execution

        // Output shows only "Laptop" processed, not all 4 orders
        firstExpensive.ifPresent(System.out::println);
    }
}

record Order(Long id, String item, int price) {}

import java.util.List;
import java.util.function.Supplier;
import java.util.stream.Stream;

public class StreamReuseDemo {
    public static void main(String[] args) {
        var orders = List.of(
            new Order(1L, "Laptop", 500),
            new Order(2L, "Mouse", 25)
        );

        // WRONG: Reusing stream throws IllegalStateException
        var stream = orders.stream();
        long count = stream.count();  // First terminal op
        // stream.forEach(System.out::println);  // Throws exception

        // CORRECT: Create new stream for each operation
        long count2 = orders.stream().count();
        orders.stream().forEach(System.out::println);

        // BEST: Store Supplier for reusability
        Supplier<Stream<Order>> streamSupplier = orders::stream;
        long count3 = streamSupplier.get().count();
        streamSupplier.get().forEach(System.out::println);
    }
}

