import java.util.stream.IntStream;

public class ParallelStreamDemo {
    public static void main(String[] args) {
        long seq = IntStream.rangeClosed(1, 1_000_000).sum();

        // parallel: splits work across the ForkJoinPool common pool
        long par = IntStream.rangeClosed(1, 1_000_000)
            .parallel()
            .sum();                 // a reduction is safe to parallelise

        System.out.println(seq + " == " + par);
    }
}
