import java.util.List;
import java.util.stream.Collectors;

public class PeekDemo {
    public static void main(String[] args) {
        var orders = List.of(
            new Order(1L, "Laptop", 500),
            new Order(2L, "Mouse", 25),
            new Order(3L, "Monitor", 300)
        );

        // Using peek to debug the pipeline
        var expensiveItems = orders.stream()
            .peek(o -> System.out.println("Original: " + o))
            .filter(o -> o.price() > 100)
            .peek(o -> System.out.println("After filter: " + o))
            .map(Order::item)
            .peek(item -> System.out.println("After map: " + item))
            .collect(Collectors.toList());

        // peek without terminal op does nothing
        orders.stream()
            .peek(o -> System.out.println("This won't print"));
    }
}

